{
  "implementation": "def solve(case):
    payload = case['payload']
    initial_state = payload['initial_state']
    max_steps = payload['max_steps']
    tool_observations = payload['tool_observations']
    transitions = payload['transitions']
    state = initial_state
    trace = []
    steps = 0
    while steps < max_steps:
        if state not in transitions:
            break
        transition = transitions[state]
        if transition['kind'] == 'final':
            final_value = transition['value']
            return {
                'status': 'completed',
                'final_value': final_value,
                'trace': trace
            }
        elif transition['kind'] == 'action':
            action = transition['action']
            observation = tool_observations.get(action)
            next_state = transition['next_by_observation'].get(observation, transition['default_next'])
            trace.append({
                'state': state,
                'action': action,
                'observation': observation,
                'next_state': next_state
            })
            state = next_state
            steps += 1
        else:
            break
    return {
        'status': 'max_steps_exceeded',
        'final_value': None,
        'trace': trace
    }"
}
